-- HEAIL HR question bank seed — Part 3 of 7 (Assessment 3: Communication, Interpersonal and Conflict resolution skills)
-- Regenerated 2026-09 from "Final_HR_Questions (2).xlsx" (sheet "Items Scored"),
-- competency codes from the accompanying hr_taxonomy_seed.sql. Run
-- hr_question_bank_wipe_before_reload.sql once first, then all 7 parts, in
-- any order. Idempotent: safe to re-run, upserts on primary key.
-- Scoring: FIB = 5/0/0/0/0 (only the correct fill earns credit); MCQ and SJT
-- = 5/3/2/1/0 (partial credit for the next-best reasoning). Option order in
-- the source is already best-to-worst (A = best) — OptionOrder shuffles for
-- display per session so "always pick position 1" doesn't max the score.
-- 585 questions.

BEGIN;

ON CONFLICT (question_id) DO UPDATE SET
  competency_code = EXCLUDED.competency_code,
  question_type = EXCLUDED.question_type,
  text = EXCLUDED.text,
  option_a = EXCLUDED.option_a,
  option_b = EXCLUDED.option_b,
  option_c = EXCLUDED.option_c,
  option_d = EXCLUDED.option_d,
  option_e = EXCLUDED.option_e,
  score_a = EXCLUDED.score_a,
  score_b = EXCLUDED.score_b,
  score_c = EXCLUDED.score_c,
  score_d = EXCLUDED.score_d,
  score_e = EXCLUDED.score_e,
  active = EXCLUDED.active;

COMMIT;
